const credentialDisplayName = 'Twitch API n8n';
// Change only this value to match your Credential display name.
// Nothing below normally needs to be changed.

const root = $input.first().json;
const credentials = Array.isArray(root?.data?.credentials)
  ? root.data.credentials
  : (Array.isArray(root?.credentials) ? root.credentials : []);

const selectionCriteria = {
  publicMetadata: { displayName: credentialDisplayName },
  requiredFieldNames: ['clientId'],
  requiredSecretNames: ['accessToken'],
};

const normalize = (value) => String(value ?? '').replace(/[\s_-]+/g, '').toLowerCase();
const matchesPublicMetadata = (item) => Object.entries(selectionCriteria.publicMetadata).every(
  ([key, expected]) => normalize(item?.metadata?.[key]) === normalize(expected),
);

const fieldsOf = (item) => Array.isArray(item?.fields) ? item.fields : [];
const hasRequiredPublicFields = (item) => selectionCriteria.requiredFieldNames.every((name) =>
  fieldsOf(item).some((field) => field?.name === name),
);
const hasRequiredSecretFields = (item) => selectionCriteria.requiredSecretNames.every((name) =>
  fieldsOf(item).some((field) => field?.name === name && field?.secret === true),
);

const candidates = credentials.filter((item) =>
  typeof item?.credentialKey === 'string' &&
  item.credentialKey.length > 0 &&
  matchesPublicMetadata(item) &&
  hasRequiredPublicFields(item) &&
  hasRequiredSecretFields(item),
);

if (candidates.length !== 1) {
  throw new Error('Expected exactly one Twitch credential candidate from public metadata; found ' + candidates.length);
}

const selected = candidates[0];
const clientId = selected?.runtimePublic?.clientId;
if (typeof clientId !== 'string' || clientId.trim().length === 0) {
  throw new Error('Selected Twitch credential has no runtimePublic.clientId');
}

return [{
  json: {
    credentialKey: selected.credentialKey,
    clientId,
    secretNames: ['accessToken'],
  },
}];

const resolved = $input.first().json;
const selection = $('Select Twitch Credential').first().json;

const accessToken = resolved?.data?.secrets?.accessToken;
const clientId = selection?.clientId;

if (typeof accessToken !== 'string' || accessToken.length === 0) {
  throw new Error('Resolve did not return accessToken');
}
if (typeof clientId !== 'string' || clientId.trim().length === 0) {
  throw new Error('Runtime-Public clientId is missing');
}

return [{
  json: {
    accessToken,
    clientId,
    credentialKey: selection.credentialKey,
  },
}];

const response = $input.first().json;
const body = response?.body ?? response;
const user = Array.isArray(body?.data) ? body.data[0] : null;
if (!user) throw new Error('Twitch users response did not contain a user record');
const selection = $('Select Twitch Credential').first().json;
return [{ json: { status: 'completed', credentialKey: selection.credentialKey, twitchHttpStatus: response?.statusCode ?? response?.status ?? 200, twitchUserId: typeof user.id === 'string' ? user.id : null, twitchDisplayName: typeof user.display_name === 'string' ? user.display_name : null, timestamp: new Date().toISOString() } }];
